export const HOME_STATION="overview";export function fovFor(n,e,t,r){if(!(e>0)||e>=t)return n;const o=n*Math.PI/360,i=360/Math.PI*Math.atan(Math.tan(o)*(t/e));return Math.min(r,i)}export function poseFor(n,e,t){const r=t.stations[n]||t.stations[HOME_STATION],o=[...r.eye];if(r.retreat&&e>0&&e<t.view.refAspect){const i=t.view.narrowAspect||.45,M=Math.min(1,(t.view.refAspect-e)/(t.view.refAspect-i)),m=r.eye.map((a,s)=>a-r.aim[s]),p=Math.hypot(...m)||1;for(let a=0;a<3;a++)o[a]+=m[a]/p*r.retreat*M}return{eye:o,aim:[...r.aim],fov:fovFor(r.fov,e,t.view.refAspect,t.view.maxFov)}}export function zoomedFov(n,e,t){const r=360/Math.PI*Math.atan(Math.tan(n*Math.PI/360)/Math.pow(2,e));return Math.min(t,r)}export function smoothstep(n){const e=Math.min(1,Math.max(0,n));return e*e*(3-2*e)}const h=(n,e,t)=>n+(e-n)*t;export function blendPose(n,e,t){return{eye:n.eye.map((r,o)=>h(r,e.eye[o],t)),aim:n.aim.map((r,o)=>h(r,e.aim[o],t)),fov:h(n.fov,e.fov,t)}}export function createGlide(n,e,t){let r=0;return{to:e,step(o){r+=Math.max(0,o);const i=t>0?smoothstep(r/t):1;return blendPose(n,e,i)},get done(){return t<=0||r>=t}}}
